        public static string GetVirtualRate(object virtualRate)
        {
            double virRate = 0;
            virRate = FormatHandler.GetDouble(virtualRate) * 100;
            string strVirRate = string.Empty;
            if (virRate < 0)
            {
                strVirRate = virRate.ToString();
            }
            else if (virRate > 0)
            {
                strVirRate = "+" + virRate.ToString();
            }
            else
            {
                strVirRate = "--";
            }
            return strVirRate;
        }

        public static bool IsTransferDaily(string custId)
        {
            DbResult rs = Select4Edit.TransferOptionSel(custId);
            if (rs != null)
            {
                string arrChar = DNAide.Core.CastAide.AsString(rs.Outputs["transferoption"]);
                if (arrChar != "")
                {
                    arrChar = arrChar.Substring(arrChar.Length - 1);
                    if (arrChar == "0")
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        /// <summary>
        /// Modified by: Lewin
        /// </summary>
        /// <param name="username"></param>
        /// <returns></returns>
        public static int GetCustomerIdByUserName(string username)
        {
            if (!string.IsNullOrEmpty(username))
            {
                var rs = SelectCustomer.CustSelByUsername(username, AppSession.SYSTEM);
                if (rs != null)
                {
                    if (rs != null && rs.Tables.Count > 0)
                        if (rs.Tables[0].Rows.Count > 0)
                        {
                            return CastAide.AsInt32(rs.Tables[0].Rows[0]["custid"]);
                        }
                }
            }

            return 0;
        }

        public static List<SiteViewModel> GroupSiteBySiteLabel(List<SiteEntity> siteEntities)
        {
            var sites = new List<SiteViewModel>();
            siteEntities
                .GroupBy(p => p.SiteLabel)
               .ToList()
               .ForEach(grp =>
               {
                   if (string.IsNullOrEmpty(grp.Key))
                   {
                       sites.AddRange(grp.Select(pt => new SiteViewModel(pt.SiteId.ToString(), pt.SiteName, null)));
                   }
                   else
                   {
                       sites.Add(new SiteViewModel(grp.Key, grp.Key, grp.Select(p => new SiteViewModel(p.SiteId.ToString(), p.SiteName, null))));
                   }
               });

            return sites;
        }
    }
